-- ----------------------------
-- Table structure for posts
-- ----------------------------
DROP TABLE IF EXISTS `posts`;
CREATE TABLE `posts`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '动态ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '发布者ID',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动态内容',
  `visibility` tinyint NULL DEFAULT 1 COMMENT '可见性: 0-私密, 1-公开, 2-粉丝可见',
  `likes_count` int UNSIGNED NULL DEFAULT 0 COMMENT '点赞数',
  `comments_count` int UNSIGNED NULL DEFAULT 0 COMMENT '评论数',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态: 0-删除, 1-正常',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_visibility`(`visibility` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE,
  CONSTRAINT `posts_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '动态表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of posts
-- ----------------------------
INSERT INTO `posts` VALUES (1, 3, '今天设计了一个新的Logo，感觉还不错！简约风格真的永不过时。大家觉得呢？', 1, 24, 3, 1, '2026-05-06 20:40:38', '2026-05-07 20:55:01');
INSERT INTO `posts` VALUES (2, 4, '周末去山里拍的风景，大自然的色彩真的太美了。每一帧都是壁纸级别！', 1, 159, 5, 1, '2026-05-06 17:40:38', '2026-05-19 21:32:43');
INSERT INTO `posts` VALUES (3, 5, '发现一家超棒的日料店，刺身新鲜到爆！推荐他们家的三文鱼和北极贝。', 1, 89, 1, 1, '2026-05-05 23:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (4, 6, '终于解决了困扰我三天的bug！原来是一个小小的拼写错误。编程就是这样，细节决定成败。', 1, 45, 2, 1, '2026-05-05 23:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (5, 7, '刚读完《百年孤独》，马尔克斯的魔幻现实主义真的太震撼了。那种孤独感贯穿全书，让人久久不能平静。强烈推荐！', 1, 234, 3, 1, '2026-05-04 23:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (6, 8, '日本京都的樱花季真的太美了！满城的粉色，仿佛置身童话世界。', 1, 313, 2, 1, '2026-05-03 23:40:38', '2026-05-19 21:32:56');
INSERT INTO `posts` VALUES (7, 9, '今天学会了拉花，虽然还不够完美，但已经能看出是个心形了！', 1, 67, 0, 1, '2026-05-03 23:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (8, 2, '分享一个今天看到的好句子：生活不是等待暴风雨过去，而是学会在雨中跳舞。', 1, 128, 5, 1, '2026-05-06 19:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (9, 3, '新做的UI界面，采用了玻璃拟态设计风格，大家觉得怎么样？', 1, 89, 4, 1, '2026-05-06 18:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (10, 4, '日落时分的海边，金色的阳光洒在海面上，美得让人窒息。', 1, 268, 6, 1, '2026-05-06 15:40:38', '2026-05-07 10:19:26');
INSERT INTO `posts` VALUES (11, 5, '这家火锅店的毛肚真的太脆了，配上秘制蘸料，绝配！', 1, 157, 4, 1, '2026-05-04 23:40:38', '2026-05-13 21:09:55');
INSERT INTO `posts` VALUES (12, 6, 'Vue3 + Spring Boot 前后端分离项目终于完成了，学到了很多东西！', 1, 78, 4, 1, '2026-05-06 11:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (13, 7, '《三体》真的太好看了，刘慈欣的想象力简直突破天际！', 1, 189, 5, 1, '2026-05-05 23:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (14, 8, '西藏的星空，没有光污染的地方，银河清晰可见。', 1, 423, 8, 1, '2026-05-02 23:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (15, 2, '今天天气真好，适合出去走走，晒晒太阳。', 1, 56, 1, 1, '2026-05-06 22:40:38', '2026-05-06 23:40:38');
INSERT INTO `posts` VALUES (23, 10, '无论世界是否待你温柔，请坚持住你的善良，因为好运会与你不期而遇', 1, 0, 0, 1, '2026-05-07 10:06:23', '2026-05-07 10:26:18');
INSERT INTO `posts` VALUES (24, 2, '今天吃到了好吃的！', 1, 0, 0, 1, '2026-05-13 21:11:26', '2026-05-13 21:11:26');
INSERT INTO `posts` VALUES (25, 2, '今天平常到了好吃哒', 1, 2, 4, 1, '2026-05-13 21:14:53', '2026-05-19 20:42:31');
INSERT INTO `posts` VALUES (26, 10, '今天是个好日子🥳', 1, 0, 0, 1, '2026-05-19 21:37:17', '2026-05-19 21:37:17');

-- ----------------------------
-- Table structure for tags
-- ----------------------------
DROP TABLE IF EXISTS `tags`;
CREATE TABLE `tags`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '标签ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签名称',
  `usage_count` int UNSIGNED NULL DEFAULT 0 COMMENT '使用次数',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name` ASC) USING BTREE,
  INDEX `idx_name`(`name` ASC) USING BTREE,
  INDEX `idx_usage_count`(`usage_count` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '标签表' ROW_FORMAT = Dynamic;

